import base64
import json
import subprocess
import sys
import zlib

subprocess.run(
    [
        sys.executable,
        "-m",
        "pip",
        "install",
        "-q",
        "qiskit",
        "qiskit-machine-learning",
        "scikit-learn",
        "pandas",
        "matplotlib",
        "seaborn",
    ],
    check=True,
)

import matplotlib

matplotlib.use("Agg")

PAYLOAD = ''

sources = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
for name, code in sources.items():
    print(f"COLAB_SOURCE_START {name}")
    scope = {"__name__": "__main__", "__file__": name}
    exec(compile(code, name, "exec"), scope, scope)
    print(f"COLAB_SOURCE_OK {name}")

print("COLAB_DAY27_SOURCE_EXECUTION_OK")
